#!/usr/bin/env python3
from __future__ import annotations

import html
import json
import math
import re
from pathlib import Path


TASK_ID = "CSX-038_Q1"
EVENT_ID = "CSX-038"
TARGET_FAMILY = "snow_phase_depth_precip_ledger"
OUT = Path(__file__).resolve().parent / "computed_gt.json"
ROOT = Path(__file__).resolve().parents[3]
PACKAGE = ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_December_2013_Middle_East_winter_storm_Alexa.json",
    "data/event_reports/event_reports_004_01_Locked_package_evidence_report.html.html",
    "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive_cold_variables.json",
    "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json",
]


RUBRIC = {
    "total_points": 20,
    "criteria": [
        {
            "name": "Ledger shape and final label",
            "points": 3,
            "description": (
                "Returns the requested compact JSON and labels the result as a marginal wet-snow "
                "point record with a large highland depth gap."
            ),
            "partial_credit": (
                "Award 1-2 points for a mostly complete ledger with a vague or partially correct label; "
                "no credit if the answer is a free-form storm summary without the requested fields."
            ),
        },
        {
            "name": "Point snow phase calculations",
            "points": 4,
            "description": (
                "Computes 1.96 cm snowfall, 16 snowfall hours, 0 freeze hours, 2.2 C minimum "
                "temperature, 46 hours at or below 5 C, 71.3 km/h maximum gust, and -3.3 C "
                "minimum wind chill."
            ),
            "partial_credit": (
                "Award up to 2 points for the snowfall and hour counts, and up to 2 points for the "
                "temperature, wind, and wind-chill values within tolerance."
            ),
        },
        {
            "name": "Reported depth scale ratios",
            "points": 4,
            "description": (
                "Computes the reported-depth to point-snow ratios near 15.31, 25.51, and 22.96 for "
                "Jerusalem low, Jerusalem high, and Amman."
            ),
            "partial_credit": (
                "Award 2-3 points if the ratios are directionally correct but one value or rounding "
                "is wrong; award 1 point for recognizing that reported depths are over 10 times the "
                "point total without computing the ratios."
            ),
        },
        {
            "name": "Gridded precipitation magnitude ledger",
            "points": 3,
            "description": (
                "Computes the three gridded mean precipitation values as 16.56, 3.68, and 1.37 mm, "
                "with largest-to-smallest and largest-to-middle ratios near 12.06 and 4.50."
            ),
            "partial_credit": (
                "Award 1-2 points for identifying the correct ordering and approximate magnitude "
                "spread while missing one mean or one ratio."
            ),
        },
        {
            "name": "Threshold logic",
            "points": 4,
            "description": (
                "Sets wet-snow point, highland depth gap, and strong precipitation spread true, while "
                "setting point-total-as-highland-depth and sustained-subfreezing-point false."
            ),
            "partial_credit": (
                "Award 1 point for each correct threshold state, up to 4 points; do not award full "
                "credit if the conclusion contradicts the computed values."
            ),
        },
        {
            "name": "Computed interpretation",
            "points": 2,
            "description": (
                "Gives one concise interpretation tying wet-snow phase, highland depth scaling, wind, "
                "and precipitation spread together without adding uncomputed impact quantities."
            ),
            "partial_credit": (
                "Award 1 point for a concise but incomplete interpretation; no credit for broad "
                "impact claims or action advice not derived from the ledger."
            ),
        },
    ],
}


def read_json(rel_path: str) -> dict:
    return json.loads((PACKAGE / rel_path).read_text(encoding="utf-8-sig", errors="replace"))


def strip_html(text: str) -> str:
    text = re.sub(r"(?is)<(script|style|noscript).*?</\1>", " ", text)
    text = re.sub(r"(?s)<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", html.unescape(text)).strip()


def extract_int(pattern: str, text: str) -> int:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"missing numeric pattern: {pattern}")
    return int(match.group(1).replace(",", ""))


def max_run(flags: list[bool]) -> int:
    best = 0
    current = 0
    for flag in flags:
        current = current + 1 if flag else 0
        best = max(best, current)
    return best


def wind_chill_c(temperature_c: float, wind_kmh: float) -> float:
    if temperature_c > 10 or wind_kmh <= 4.8:
        return temperature_c
    wind_factor = math.pow(wind_kmh, 0.16)
    return 13.12 + 0.6215 * temperature_c - 11.37 * wind_factor + 0.3965 * temperature_c * wind_factor


def rounded(value: float, digits: int = 2) -> float:
    return round(float(value), digits)


def main() -> None:
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_December_2013_Middle_East_winter_storm_Alexa.json"
    )
    open_meteo = read_json("data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive_cold_variables.json")
    era5 = read_json("data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json("data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json("data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json")

    report_text = strip_html(
        (PACKAGE / "data/event_reports/event_reports_004_01_Locked_package_evidence_report.html.html").read_text(
            encoding="utf-8", errors="replace"
        )
    )
    report_snow = {
        "jerusalem_min_cm": extract_int(r"Jerusalem with ([0-9,]+) to [0-9,]+ centimeters", report_text),
        "jerusalem_max_cm": extract_int(r"Jerusalem with [0-9,]+ to ([0-9,]+) centimeters", report_text),
        "amman_cm": extract_int(r"Amman, Jordan, received about ([0-9,]+) cm", report_text),
    }

    hourly = open_meteo["hourly"]
    daily = open_meteo["daily"]
    hourly_temp = hourly["temperature_2m"]
    hourly_snow = hourly["snowfall"]
    hourly_wind = hourly["wind_speed_10m"]
    hourly_gust = hourly["wind_gusts_10m"]
    daily_snow = daily["snowfall_sum"]
    snow_flags = [value > 0 for value in hourly_snow]
    wind_chills = [wind_chill_c(temp, wind) for temp, wind in zip(hourly_temp, hourly_wind)]

    point_snow_cm = rounded(sum(daily_snow), 2)
    point_phase = {
        "snow_cm": point_snow_cm,
        "snow_hours": sum(snow_flags),
        "freeze_hours": sum(value <= 0 for value in hourly_temp),
        "min_temp_c": rounded(min(hourly_temp), 1),
        "hours_le_5c": sum(value <= 5 for value in hourly_temp),
        "max_gust_kmh": rounded(max(hourly_gust), 1),
        "min_wind_chill_c": rounded(min(wind_chills), 1),
    }

    depth_ratios = {
        "jerusalem_min_to_point": rounded(report_snow["jerusalem_min_cm"] / point_snow_cm, 2),
        "jerusalem_max_to_point": rounded(report_snow["jerusalem_max_cm"] / point_snow_cm, 2),
        "amman_to_point": rounded(report_snow["amman_cm"] / point_snow_cm, 2),
    }

    precip_values = {
        "largest_mean_mm": rounded(era5["stats"]["precipitation_sum_mm_mean"], 2),
        "middle_mean_mm": rounded(chirps["stats"]["chirps_event_precip_mm_mean"], 2),
        "smallest_mean_mm": rounded(gpm["stats"]["gpm_event_precip_mm_mean"], 2),
    }
    precip_ledger = {
        **precip_values,
        "largest_to_smallest_ratio": rounded(
            era5["stats"]["precipitation_sum_mm_mean"] / gpm["stats"]["gpm_event_precip_mm_mean"], 2
        ),
        "largest_to_middle_ratio": rounded(
            era5["stats"]["precipitation_sum_mm_mean"] / chirps["stats"]["chirps_event_precip_mm_mean"], 2
        ),
    }

    logic_flags = {
        "wet_snow_point": point_phase["snow_hours"] > 0
        and point_phase["freeze_hours"] == 0
        and point_phase["min_temp_c"] > 0,
        "highland_depth_gap": min(depth_ratios.values()) >= 10.0,
        "point_total_as_highland_depth": min(depth_ratios.values()) <= 1.25,
        "sustained_subfreezing_point": point_phase["freeze_hours"] >= 12,
        "strong_precip_spread": precip_ledger["largest_to_smallest_ratio"] >= 5.0
        or precip_ledger["largest_to_middle_ratio"] >= 3.0,
    }

    primary_gt = {
        "target_family": TARGET_FAMILY,
        "answer_label": "marginal_wet_snow_point_with_highland_depth_gap",
        "point_phase": point_phase,
        "reported_depth_ratios": depth_ratios,
        "gridded_precip": precip_ledger,
        "logic_flags": logic_flags,
        "computed_interpretation": (
            "The point record shows wet-snow conditions and strong wind, while reported highland "
            "depths are 15-26 times the point snowfall and gridded precipitation means differ by "
            "roughly 4.5-12 times."
        ),
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L4",
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_window": {
                "start_date": anchor["temporal_window"]["start_date"],
                "end_date": anchor["temporal_window"]["end_date"],
            },
            "point_weather_full": {
                **point_phase,
                "snow_days": [daily["time"][index] for index, value in enumerate(daily_snow) if value > 0],
                "max_consecutive_snow_hours": max_run(snow_flags),
                "event_hours": len(hourly["time"]),
            },
            "reported_snow_cm": report_snow,
            "reported_depth_ratios": depth_ratios,
            "precip_detail": {
                "era5_land_mean_mm": era5["stats"]["precipitation_sum_mm_mean"],
                "gpm_mean_mm": gpm["stats"]["gpm_event_precip_mm_mean"],
                "chirps_mean_mm": chirps["stats"]["chirps_event_precip_mm_mean"],
                "era5_to_gpm_ratio": precip_ledger["largest_to_smallest_ratio"],
                "era5_to_chirps_ratio": precip_ledger["largest_to_middle_ratio"],
            },
        },
        "decision_rule": {
            "wet_snow_point": "snow_hours > 0, freeze_hours == 0, and min_temp_c > 0",
            "highland_depth_gap": "minimum reported-depth-to-point-snow ratio >= 10",
            "point_total_as_highland_depth": "minimum reported-depth-to-point-snow ratio <= 1.25",
            "sustained_subfreezing_point": "freeze_hours >= 12",
            "strong_precip_spread": "largest_to_smallest_ratio >= 5 or largest_to_middle_ratio >= 3",
        },
        "tolerances": {
            "snow_cm": 0.05,
            "temperature_c": 0.2,
            "wind_kmh": 1.0,
            "wind_chill_c": 0.2,
            "ratio": 0.05,
            "precip_mm": 0.1,
        },
        "rubric": RUBRIC,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }
    OUT.write_text(json.dumps(computed_gt, ensure_ascii=True, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
